      productData = Object.assign({}, productData, { options: sortedOptions });
    }
  }

  if (needsNativeVariantPicker(productData)) {
    var nativeRoot = wrapper.closest('.product__info-container');
    builder.setAttribute('hidden', 'hidden');
    if (nativeRoot) {
      nativeRoot.classList.remove('product__info-container--matching-set');
      nativeRoot.setAttribute('data-has-matching-set', 'false');
      nativeRoot.setAttribute('data-matching-set-fallback', 'true');
      nativeRoot.removeAttribute('data-type-implicit');
