      escapeHtml(getFitModalId()) +
      '-title" tabindex="-1">' +
      '<div class="dlm-fit-modal__header">' +
      '<div>' +
      '<p class="dlm-fit-modal__eyebrow">' +
      escapeHtml(groupedLabel || compareLabel || 'Size chart') +
      '</p>' +
      '<h2 class="dlm-fit-modal__title" id="' +
      escapeHtml(getFitModalId()) +
      '-title">Find fit</h2>' +
      '</div>' +
      '<button type="button" class="dlm-fit-modal__close" data-fit-modal-close aria-label="' +
      escapeHtml(uiLabel('closeSizeDetails', 'Close size details')) +
      '">×</button>' +
      '</div>' +
      '<div class="dlm-fit-modal__tabs" data-fit-modal-tabs></div>' +
      '<div class="dlm-fit-modal__body" data-fit-modal-body></div>' +
      '</section>';

    (sizeGuideRoot || document.body).appendChild(fitModal);
    fitModal.addEventListener('click', function (event) {
      if (event.target.closest('[data-fit-modal-close]')) closeFitModal();
    });
    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && fitModal && !fitModal.hasAttribute('hidden')) closeFitModal();
    });

    return fitModal;
  }

  function getFitModalGroups() {
    if (groups && groups.length) return groups;
    if (parsed && parsed.headers && parsed.rows && parsed.rows.length) {
      return [
        {
          key: 'all',
          label: compareLabel || 'Size chart',
          helper: '',
          headers: parsed.headers,
          rows: parsed.rows,
        },
      ];
    }
    return [];
  }

  function fitGarmentKeysCompatible(selectedGarmentKey, candidateGarmentKey) {
    if (!selectedGarmentKey || !candidateGarmentKey || selectedGarmentKey === candidateGarmentKey) return true;
    var shirtFamily = ['shirt', 'shorts', 'shirtShortsSet'];
    return shirtFamily.indexOf(selectedGarmentKey) !== -1 && shirtFamily.indexOf(candidateGarmentKey) !== -1;
  }

  function getFitHeaderGarmentKeys(header) {
    if (!header) return [];
    if (typeof header === 'object') return getGarmentKeys([header.raw, header.label].filter(Boolean).join(' '));
    return getGarmentKeys(header);
  }

  function getFitRoleFamilyKey(roleKey) {
    if (roleKey === 'mother' || roleKey === 'father' || roleKey === 'adult') return 'adult';
    if (roleKey === 'girl' || roleKey === 'boy' || roleKey === 'child' || roleKey === 'baby') return 'child';
    return '';
  }

  function getFitRowRoleKey(rowLabel) {
    var parsedRole = parseRoleFromSizeLabel(rowLabel);
    if (parsedRole && parsedRole.key) return parsedRole.key;
    return inferBaseRoleKeyFromStandaloneSize(rowLabel);
  }

  function pruneFitGroupForRole(group, roleKey) {
    if (!group || !roleKey || !group.headers || !group.rows || !group.rows.length) return group || null;

    var roleFamilyKey = getFitRoleFamilyKey(roleKey);
    if (!roleFamilyKey) return group;

    var rowMatches = group.rows.map(function (row) {
      var rowRoleKey = getFitRowRoleKey(row && row[0]);
      if (!rowRoleKey) return null;
      return areSizeGuideRolesCompatible(roleKey, rowRoleKey) || rowRoleKey === roleFamilyKey;
    });
    var hasMatchingRows = rowMatches.some(function (matches) { return matches === true; });
    var groupHasRole = !!getFitRoleFamilyKey(group.key);
    var groupMatchesRole = groupHasRole && areSizeGuideRolesCompatible(roleKey, group.key);
    if (groupHasRole && !groupMatchesRole) return null;
    if (!hasMatchingRows && !groupMatchesRole) return null;

    var filteredRows = group.rows.filter(function (_row, index) {
      return rowMatches[index] === true || (rowMatches[index] === null && groupMatchesRole);
    });
    if (!filteredRows.length) return null;

    var prunedGroup = pruneGuideGroupColumns(group.headers, filteredRows);
    if (!prunedGroup.rows.length) return null;

    return {
      key: roleKey,
      label: getLocalizedRoleLabelByKey(roleKey) || group.label,
      helper: getRoleFitCopy(roleKey) || group.helper,
      headers: prunedGroup.headers,
      rows: prunedGroup.rows,
    };
  }

  function pruneFitGroupForGarment(group, garmentKey, hasDeclaredGarmentContext) {
    if (!group || !garmentKey || !group.headers || !group.rows) return group || null;

    var hasGarmentHeaders = group.headers.some(function (header, index) {
      return index > 0 && getFitHeaderGarmentKeys(header).length > 0;
    });
    if (!hasGarmentHeaders) return group;

    var matchedSpecificHeader = false;
    var keepIndexes = group.headers
      .map(function (_header, index) {
        return index;
      })
      .filter(function (index) {
        if (index === 0) return true;
        var headerKeys = getFitHeaderGarmentKeys(group.headers[index]);
        if (!headerKeys.length) return hasDeclaredGarmentContext || isSharedFitMeasurementHeader(group.headers[index]);
        var matches = headerKeys.some(function (headerKey) {
          return fitGarmentKeysCompatible(garmentKey, headerKey);
        });
        if (matches) matchedSpecificHeader = true;
        return matches;
      });

    if ((!matchedSpecificHeader && !hasDeclaredGarmentContext) || keepIndexes.length <= 1) return null;

    var pruned = pruneGuideGroupColumns(
      keepIndexes.map(function (index) {
        return group.headers[index];
      }),
      group.rows.map(function (row) {
        return keepIndexes.map(function (index) {
          return row[index];
        });
      })
    );

    if (!pruned.rows.length || !pruned.rows.some(function (row) {
      return row.slice(1).some(function (value) { return !isGuideEmptyValue(value); });
    })) {
      return null;
    }

    return {
      key: group.key,
      label: group.label,
      helper: group.helper,
      headers: pruned.headers,
      rows: pruned.rows,
    };
  }

  function findActiveFitGroupInList(groupList, groupKey, roleKey, garmentKey) {
    var modalGroups = groupList || [];
    if (!modalGroups.length) return null;

    var normalizedGroupKey = String(groupKey || '').trim();
    var normalizedRoleKey = String(roleKey || '').trim();
    var findExact = function (key) {
      if (!key) return null;
      return modalGroups.find(function (group) {
        return String(group.key || '') === key;
      }) || null;
    };
    var findCompatible = function (key) {
      if (!key) return null;
      return modalGroups.find(function (group) {
        return areSizeGuideRolesCompatible(key, String(group.key || ''));
      }) || null;
    };

    var activeGroup =
      findExact(normalizedRoleKey) ||
      findCompatible(normalizedRoleKey) ||
      findExact(normalizedGroupKey) ||
      findCompatible(normalizedGroupKey) ||
      findExact('all') ||
      (!normalizedRoleKey && !normalizedGroupKey ? modalGroups[0] : null);

    if (!activeGroup) return null;
    var rolePrunedGroup = pruneFitGroupForRole(activeGroup, normalizedRoleKey || normalizedGroupKey);
    if (!rolePrunedGroup) return null;
    return pruneFitGroupForGarment(rolePrunedGroup, garmentKey) || (!garmentKey ? rolePrunedGroup : null);
  }

  function getFitGroupFromProductTables(groupKey, roleKey, garmentKey) {
    var sourceRoot = getCurrentDescriptionRoot();
    var sourceTables = sourceRoot
      ? Array.from(sourceRoot.querySelectorAll('table#size-chart, table[id*="size-chart"], table.size-chart'))
      : [];
    if (!sourceTables.length) return null;
    var allowGeneric = sourceTables.length === 1 && getProductTypeValues(productData).length <= 1;
    if (!garmentKey && !allowGeneric) return null;
    var matches = [];

    for (var index = 0; index < sourceTables.length; index += 1) {
      var table = sourceTables[index];
      if (getGarmentKeys(getSizeGuideTableContextText(table)).length > 1) continue;
      var contextGarmentKey = getSizeChartGarmentKey(table, productData, sourceTables.length);
      if (contextGarmentKey && garmentKey !== contextGarmentKey) continue;

      var tableParsed = parseSizeGuideTable(table);
      if (!tableParsed) continue;
      if (!contextGarmentKey && !allowGeneric && !tableParsed.headers.some(function (header, headerIndex) {
        return headerIndex > 0 && getFitHeaderGarmentKeys(header).indexOf(garmentKey) !== -1;
      })) continue;
      var tableGroups = buildSizeGuideGroups(tableParsed);
      var activeGroup = findActiveFitGroupInList(tableGroups.length ? tableGroups : [{
        key: 'all',
        label: compareLabel || 'Size chart',
        helper: '',
        headers: tableParsed.headers,
        rows: tableParsed.rows,
      }], groupKey, roleKey, contextGarmentKey ? '' : garmentKey);
      if (activeGroup && contextGarmentKey) activeGroup = pruneFitGroupForGarment(activeGroup, garmentKey, true);
      if (activeGroup) {
        activeGroup.sourceTable = table;
        activeGroup.garmentKey = contextGarmentKey || garmentKey || '';
        matches.push(activeGroup);
      }
    }

    return matches.length === 1 ? matches[0] : null;
  }

  function getFitModalActiveGroup(groupKey, roleKey, garmentKey) {
    var modalGroups = getFitModalGroups();
    return findActiveFitGroupInList(modalGroups, groupKey, roleKey, garmentKey);
  }

  function bindFitModalEvents() {
    if (!fitModal) return;
    fitModal.querySelectorAll('[data-fit-modal-group]').forEach(function (button) {
      button.addEventListener('click', function () {
        var nextGroup = button.getAttribute('data-fit-modal-group');
        if (!nextGroup || nextGroup === activeFitModalGroupKey) return;
        activeFitModalGroupKey = nextGroup;
        renderFitModal(activeFitModalGroupKey);
      });
    });
  }

  function renderFitModal(groupKey, roleKey) {
    var modal = ensureFitModal();
    var modalGroups = getFitModalGroups();
    var activeGroup = getFitModalActiveGroup(groupKey, roleKey, '');
    var tabs = modal.querySelector('[data-fit-modal-tabs]');
    var body = modal.querySelector('[data-fit-modal-body]');
    var title = modal.querySelector('.dlm-fit-modal__title');

    if (!activeGroup || !body) return false;
    activeFitModalGroupKey = activeGroup.key;
    if (title) title.textContent = activeGroup.label || 'Find fit';

    if (tabs) {
      if (modalGroups.length > 1) {
        tabs.innerHTML = modalGroups
          .map(function (group) {
            var isActive = String(group.key) === String(activeGroup.key);
            return (
              '<button type="button" class="dlm-fit-modal__tab' +
              (isActive ? ' is-active' : '') +
              '" data-fit-modal-group="' +
              escapeHtml(group.key) +
              '" aria-pressed="' +
              (isActive ? 'true' : 'false') +
              '">' +
              escapeHtml(group.label || group.key) +
              '</button>'
            );
          })
          .join('');
        tabs.removeAttribute('hidden');
      } else {
        tabs.innerHTML = '';
        tabs.setAttribute('hidden', 'hidden');
      }
    }

    body.innerHTML =
      renderGuideContentToolbar(activeGroup.headers || [], activeGroup.label || '') +
      renderTableCard(
        activeGroup.headers || [],
        activeGroup.rows || [],
        activeGroup.label || '',
        activeGroup.helper || '',
        getSelectedGuideMatch(getSelectedSizeState()),
        activeGroup.key
      );

    bindFitModalEvents();
    bindUnitToggleEvents();
    return true;
  }

  function closeInlineFitPanel(panel, trigger) {
    if (panel) {
      panel.setAttribute('hidden', 'hidden');
      panel.innerHTML = '';
    }
    if (trigger) trigger.setAttribute('aria-expanded', 'false');
  }

  function closeSelectedSizePanelForTrigger(trigger) {
    if (!trigger) return;
    var card = trigger.closest('[data-instance-card]');
    if (!card) return;
    var instanceId = card.getAttribute('data-instance-card');
    if (!instanceId) return;

    card.querySelectorAll('[data-selected-size-panel]').forEach(function (panel) {
      if (panel.getAttribute('data-selected-size-panel') === instanceId) panel.remove();
    });
  }

  function getFitTriggerSelectedMatch(trigger, activeGroup) {
    if (!trigger || !activeGroup || !activeGroup.rows || !activeGroup.rows.length) return null;
    var sizeLabel = String(trigger.getAttribute('data-fit-size-label') || '').trim();
    if (!sizeLabel) return null;

    var roleKey = String(trigger.getAttribute('data-fit-role-key') || activeGroup.key || '').trim();
    var roleLabel = activeGroup.label || '';
    var comparableValues = [sizeLabel];
    if (roleLabel) comparableValues.push(roleLabel + ' ' + sizeLabel);

    var selectedState = {
      rawValue: sizeLabel,
      rawText: sizeLabel,
      displayValue: sizeLabel,
      roleKey: roleKey,
      roleLabel: roleLabel,
      sizeLabel: sizeLabel,
      tokens: buildSizeMatchTokens(comparableValues),
      comparableValues: comparableValues,
      comparable: getPrimaryComparableSize(comparableValues),
    };

    var bestRow = null;
    var bestScore = -Infinity;
    var ambiguousRow = false;
    activeGroup.rows.forEach(function (row) {
      var rowTokens = buildSizeMatchTokens(getGuideRowValues(row[0]));
      if (!Object.keys(rowTokens).some(function (token) { return selectedState.tokens[token]; })) return;
      var score = getGuideRowMatchScore(row[0], selectedState, activeGroup.key);
      if (score > bestScore) {
        bestScore = score;
        bestRow = row;
        ambiguousRow = false;
      } else if (score === bestScore) {
        ambiguousRow = true;
      }
    });

    if (!bestRow || bestScore === -Infinity || ambiguousRow) return null;
    return {
      label: activeGroup.label || '',
      helper: activeGroup.helper || '',
      headers: activeGroup.headers,
      row: bestRow,
      roleKey: activeGroup.key || '',
    };
  }

  function renderInlineFitPanel(trigger, forceOpen) {
    if (!trigger) return false;
    var targetId = trigger.getAttribute('aria-controls') || '';
    var panel = targetId ? document.getElementById(targetId) : null;
    if (!panel) return false;

    var isOpen = !panel.hasAttribute('hidden');
    if (isOpen && !forceOpen) {
      closeInlineFitPanel(panel, trigger);
      return true;
    }

    if (isInlineFitMobileViewport()) {
      closeSelectedSizePanelForTrigger(trigger);
    }

    sizeGuideRoot.querySelectorAll('[data-fit-inline-panel]').forEach(function (otherPanel) {
      if (otherPanel === panel) return;
      var otherTrigger = null;
      sizeGuideRoot.querySelectorAll('[data-pdp-fit-inline-trigger]').forEach(function (candidate) {
        if (candidate.getAttribute('aria-controls') === otherPanel.id) otherTrigger = candidate;
      });
      closeInlineFitPanel(otherPanel, otherTrigger);
    });

    var triggerGroupKey = trigger.getAttribute('data-fit-group-key');
    var triggerRoleKey = trigger.getAttribute('data-fit-role-key');
    var triggerGarmentKey = trigger.getAttribute('data-fit-garment-key');
    var pendingAxis = trigger.getAttribute('data-fit-pending-axis');
    var activeGroup = pendingAxis ? null : getFitGroupFromProductTables(triggerGroupKey, triggerRoleKey, triggerGarmentKey);
    if (!activeGroup) {
      panel.innerHTML = '<p role="status">' + escapeHtml(pendingAxis
        ? uiLabel('pickAxis', 'Pick a {axis}', { axis: pendingAxis })
        : uiLabel('fitUnavailable', 'The size guide is unavailable for this selection.')) + '</p>';
      panel.removeAttribute('hidden');
      trigger.setAttribute('aria-expanded', 'true');
      return true;
    }

    var activeHeaders = activeGroup.headers || [];
    var mobileMinWidthRem = 5.2 + Math.max(activeHeaders.length - 1, 0) * 7;
    panel.style.setProperty('--dlm-fit-table-min-width', mobileMinWidthRem.toFixed(1) + 'rem');

    var selectedMatch = getFitTriggerSelectedMatch(trigger, activeGroup);
    panel.innerHTML =
      '<div class="product-matching-set__inline-fit-panel-bar">' +
      '<strong>' +
      escapeHtml(activeGroup.label || 'Size chart') +
      '</strong>' +
      renderGuideUnitToggle(activeHeaders) +
      '</div>' +
      renderTableCard(
        activeHeaders,
        activeGroup.rows || [],
        '',
        '',
        selectedMatch,
        activeGroup.key
      );
    bindInlineFitPanelScroll(panel);
    panel.removeAttribute('hidden');
    trigger.setAttribute('aria-expanded', 'true');
    bindUnitToggleEvents();
    return true;
  }

  function renderVisibleInlineFitPanels() {
    sizeGuideRoot.querySelectorAll('[data-pdp-fit-inline-trigger][aria-expanded="true"]').forEach(function (trigger) {
      renderInlineFitPanel(trigger, true);
    });
  }

  function updateInlineFitFrozenColumn(panel, tableWrap) {
    if (!panel || !tableWrap) return;

    var overlay = tableWrap.querySelector('[data-dlm-fit-frozen-column]');
    if (!isInlineFitMobileViewport()) {
      if (overlay) overlay.remove();
      tableWrap.removeAttribute('data-dlm-fit-frozen-overlay');
      panel.style.removeProperty('--dlm-fit-frozen-width');
      panel.style.removeProperty('--dlm-fit-frozen-height');
      panel.style.removeProperty('--dlm-fit-overlay-scroll-left');
      panel.style.removeProperty('--dlm-fit-scroll-left');
      return;
    }

    var table = tableWrap.querySelector('.matching-size-guide__table');
    var firstCells = table
      ? Array.prototype.slice.call(table.querySelectorAll('thead th:first-child, tbody td:first-child'))
      : [];
    if (!table || !firstCells.length) {
      if (overlay) overlay.remove();
      tableWrap.removeAttribute('data-dlm-fit-frozen-overlay');
      return;
    }

    if (!overlay) {
      overlay = document.createElement('div');
      overlay.className = 'dlm-fit-frozen-column';
      overlay.setAttribute('data-dlm-fit-frozen-column', '');
      tableWrap.appendChild(overlay);
    }

    var tableRect = table.getBoundingClientRect();
    var longestCellText = firstCells.reduce(function (maxLength, cell) {
      return Math.max(maxLength, String(cell.textContent || '').trim().length);
    }, 0);
    var compactTextWidth = Math.min(86, Math.max(42, longestCellText * 7 + 18));
    var overlayWidth = Math.min(tableWrap.clientWidth || compactTextWidth, compactTextWidth);
    var overlayHeight = Math.max(table.offsetHeight || tableRect.height || 0, tableWrap.clientHeight || 0);

    panel.style.setProperty('--dlm-fit-frozen-width', Math.ceil(overlayWidth) + 'px');
    panel.style.setProperty('--dlm-fit-frozen-height', Math.ceil(overlayHeight) + 'px');
    tableWrap.setAttribute('data-dlm-fit-frozen-overlay', 'true');
    overlay.innerHTML = '';

    firstCells.forEach(function (cell, index) {
      var cellRect = cell.getBoundingClientRect();
      var frozenCell = document.createElement('div');
      var isHeader = cell.tagName === 'TH';
      var isSelected = !!(cell.parentElement && cell.parentElement.classList.contains('is-selected'));
      frozenCell.className =
        'dlm-fit-frozen-column__cell' +
        (isHeader ? ' dlm-fit-frozen-column__cell--head' : '') +
        (isSelected ? ' dlm-fit-frozen-column__cell--selected' : '');
      frozenCell.setAttribute('data-dlm-fit-frozen-row-index', String(index));
      frozenCell.textContent = String(cell.textContent || '').trim();
      frozenCell.style.top = Math.round(cellRect.top - tableRect.top) + 'px';
      frozenCell.style.height = Math.max(1, Math.round(cellRect.height)) + 'px';
      overlay.appendChild(frozenCell);
    });
  }

  function syncInlineFitFrozenActiveCell(tableWrap, activeRow) {
    if (!tableWrap) return;
    var overlay = tableWrap.querySelector('[data-dlm-fit-frozen-column]');
    if (!overlay) return;

    var activeIndex = -1;
    if (activeRow && activeRow.parentElement) {
      var rows = Array.prototype.slice.call(activeRow.parentElement.children || []);
      activeIndex = rows.indexOf(activeRow) + 1;
    }

    overlay.querySelectorAll('[data-dlm-fit-frozen-row-index]').forEach(function (cell) {
      var rowIndex = Number(cell.getAttribute('data-dlm-fit-frozen-row-index'));
      cell.classList.toggle('dlm-fit-frozen-column__cell--active', rowIndex === activeIndex);
    });
  }

  function bindInlineFitFrozenColumnInteraction(tableWrap) {
    if (!tableWrap || tableWrap.getAttribute('data-dlm-fit-frozen-interaction-bound') === 'true') return;
    tableWrap.setAttribute('data-dlm-fit-frozen-interaction-bound', 'true');

    tableWrap.addEventListener('pointermove', function (event) {
      syncInlineFitFrozenActiveCell(tableWrap, event.target && event.target.closest ? event.target.closest('tbody tr') : null);
    }, { passive: true });

    tableWrap.addEventListener('pointerleave', function () {
      syncInlineFitFrozenActiveCell(tableWrap, null);
    }, { passive: true });

    tableWrap.addEventListener('focusin', function (event) {
      syncInlineFitFrozenActiveCell(tableWrap, event.target && event.target.closest ? event.target.closest('tbody tr') : null);
    });

    tableWrap.addEventListener('focusout', function () {
      window.setTimeout(function () {
        syncInlineFitFrozenActiveCell(tableWrap, tableWrap.querySelector('tbody tr:focus, tbody tr:focus-within'));
      }, 0);
    });
  }

  function bindInlineFitPanelScroll(panel) {
    if (!panel) return;
    var tableWrap = panel.querySelector('.matching-size-guide__table-wrap');
    if (!tableWrap) return;
    var needsScrollTransform = null;
    var syncScroll = function () {
      var rawScrollLeft = tableWrap.scrollLeft || 0;
      var maxScrollLeft = Math.max(0, (tableWrap.scrollWidth || 0) - (tableWrap.clientWidth || 0));
      var scrollLeft = Math.min(maxScrollLeft, Math.max(0, rawScrollLeft));
      var offset = 0;
      if (Math.abs(rawScrollLeft - scrollLeft) > 0.5) tableWrap.scrollLeft = scrollLeft;
      panel.style.setProperty('--dlm-fit-overlay-scroll-left', String(scrollLeft) + 'px');
      if (scrollLeft > 0) {
        if (needsScrollTransform === null) {
          panel.style.setProperty('--dlm-fit-scroll-left', '0px');
          var firstCell = tableWrap.querySelector('tbody td:first-child, thead th:first-child');
          var wrapRect = tableWrap.getBoundingClientRect();
          var cellRect = firstCell ? firstCell.getBoundingClientRect() : null;
          needsScrollTransform = !!(cellRect && Math.abs(wrapRect.left - cellRect.left) > 1);
        }
        if (needsScrollTransform) offset = scrollLeft;
      }
      panel.style.setProperty('--dlm-fit-scroll-left', String(offset) + 'px');
    };
    updateInlineFitFrozenColumn(panel, tableWrap);
    bindInlineFitFrozenColumnInteraction(tableWrap);
    syncScroll();
    window.setTimeout(function () {
      updateInlineFitFrozenColumn(panel, tableWrap);
      syncScroll();
    }, 0);
    window.setTimeout(function () {
      updateInlineFitFrozenColumn(panel, tableWrap);
      syncScroll();
    }, 250);
    tableWrap.addEventListener('scroll', syncScroll, { passive: true });
  }

  function openFitModal(trigger) {
    var groupKey = trigger ? trigger.getAttribute('data-fit-group-key') : '';
    var roleKey = trigger ? trigger.getAttribute('data-fit-role-key') : '';
    if (!renderFitModal(groupKey, roleKey)) return false;

    lastFitModalTrigger = trigger || null;
    fitModal.removeAttribute('hidden');
    fitModal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('dlm-fit-modal-open');

    var focusTarget = fitModal.querySelector('.dlm-fit-modal__dialog') || fitModal;
    window.setTimeout(function () {
      try { focusTarget.focus({ preventScroll: true }); } catch (_error) { focusTarget.focus(); }
    }, 0);
    return true;
  }

  function closeFitModal() {
    if (!fitModal) return;
    fitModal.setAttribute('hidden', 'hidden');
    fitModal.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('dlm-fit-modal-open');
    if (lastFitModalTrigger) {
      try { lastFitModalTrigger.focus({ preventScroll: true }); } catch (_error) { lastFitModalTrigger.focus(); }
    }
  }

  function bindUnitToggleEvents() {
    sizeGuideRoot.querySelectorAll('[data-size-guide-unit]').forEach(function (button) {
      button.addEventListener('click', function () {
        var nextUnitSystem = button.getAttribute('data-size-guide-unit');
        if (nextUnitSystem !== 'metric' && nextUnitSystem !== 'imperial') return;
        if (nextUnitSystem === selectedUnitSystem) return;
        selectedUnitSystem = nextUnitSystem;
        storeSizeGuideUnitSystem(selectedUnitSystem);
        renderGuide();
        if (fitModal && !fitModal.hasAttribute('hidden')) {
          renderFitModal(activeFitModalGroupKey);
        }
        renderVisibleInlineFitPanels();
      });
    });
  }

  function renderGuide() {
    descriptionRoot = getCurrentDescriptionRoot();
    imagePresetGuide = descriptionRoot ? getImageBasedSizeGuidePreset(descriptionRoot) : null;
    if (descriptionRoot) hideRedundantSizeGuideSources(descriptionRoot, imagePresetGuide);

    sizeTable = getSizeGuideTable(sizeGuideRoot, getCurrentSizeSelect(), getSelectedGuideTypeValue());
    if (!sizeTable) return;

    parsed = parseSizeGuideTable(sizeTable);
    if (!parsed) return;

    groups = buildSizeGuideGroups(parsed);

    var selectedState = getSelectedSizeState();
    var selectedMatch = getSelectedGuideMatch(selectedState);
    var guideSummaryLabel = groups.length > 1 ? groupedLabel : compareLabel;
    var guideHeadersForToggle = getGuideHeadersForUnitToggle(groups, parsed.headers);
    var guideToolbarHtml = selectedMatch ? '' : renderGuideContentToolbar(guideHeadersForToggle, guideSummaryLabel);

    renderSelectedGuideSnapshot(selectedMatch, selectedState);

    if (groups.length >= 1) {
      if (summary) summary.textContent = guideSummaryLabel;
      if (groups.length > 1) {
        content.innerHTML =
          guideToolbarHtml +
          '<div class="matching-size-guide__grid">' +
          groups
            .map(function (group) {
              return renderTableCard(group.headers, group.rows, group.label, group.helper, selectedMatch, group.key);
            })
            .join('') +
          '</div>';
      } else {
        content.innerHTML =
          guideToolbarHtml +
          renderTableCard(groups[0].headers, groups[0].rows, groups[0].label, groups[0].helper, selectedMatch, groups[0].key);
      }
    } else {
      if (summary) summary.textContent = compareLabel;
      content.innerHTML = guideToolbarHtml + renderTableCard(parsed.headers, parsed.rows, '', '', selectedMatch);
    }

    bindUnitToggleEvents();
    details.removeAttribute('hidden');
  }

  if (sizeTable && parsed) {
    renderGuide();
  } else {
    loadDefaultLocaleSizeGuideSource().then(function (loaded) {
      if (loaded) scheduleGuideRender(0);
    });
  }

  sizeGuideRoot.addEventListener('change', function (event) {
    var target = event && event.target;
    if (!target) return;

    var optionName = getOptionNameFromControl(target);
    if (!optionName || (!isSizeLikeLabel(optionName) && !isTypeLikeLabel(optionName))) return;

    scheduleGuideRender(ON_CHANGE_DEBOUNCE_TIMER + 25);
  });

  sizeGuideRoot.addEventListener('click', function (event) {
    var inlineTrigger = event && event.target ? event.target.closest('[data-pdp-fit-inline-trigger]') : null;
    if (inlineTrigger) {
      if (event.defaultPrevented) return;
      if (event.button && event.button !== 0) return;
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      if (renderInlineFitPanel(inlineTrigger)) event.preventDefault();
      return;
    }

    var trigger = event && event.target ? event.target.closest('[data-pdp-fit-modal-trigger]') : null;
    if (!trigger) return;
    if (event.defaultPrevented) return;
    if (event.button && event.button !== 0) return;
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    if (openFitModal(trigger)) event.preventDefault();
  });

  if (typeof subscribe === 'function' && typeof PUB_SUB_EVENTS !== 'undefined' && PUB_SUB_EVENTS.variantChange) {
    subscribe(PUB_SUB_EVENTS.variantChange, function (event) {
      if (!event || !event.data || String(event.data.sectionId || '') !== String(sectionId)) return;
      scheduleGuideRender(0);
    });
  }
}

function parseSizeGuideTable(table) {
  var rows = Array.from(table.querySelectorAll('tr'));
  if (rows.length < 2) return null;

  var headers = Array.from(rows[0].querySelectorAll('th, td')).map(function (cell) {
    return parseSizeGuideHeaderText(cellText(cell));
  });
  if (!headers.length) return null;

  var bodyRows = rows
    .slice(1)
    .map(function (row) {
      return Array.from(row.querySelectorAll('td')).map(function (cell) {
        return cellText(cell);
      });
    })
    .filter(function (cells) {
      return cells.length === headers.length;
    });

  if (!bodyRows.length) return null;
  headers = enrichSizeGuideHeaders(headers, bodyRows);

  return {
    headers: headers,
    rows: bodyRows,
  };
}

function parseSizeGuideHeaderText(headerText) {
  var raw = String(headerText || '').trim();
  var match = raw.match(/\(([^)]+)\)\s*$/);
  var units = [];
  var label = raw;

  if (match) {
    label = raw.slice(0, match.index).trim();
    units = match[1]
      .split('/')
      .map(function (unit) {
        return String(unit || '').trim();
      })
      .filter(Boolean);
  }

  return {
    raw: raw,
    label: label || raw,
    units: units,
  };
}

function normalizeGuideUnit(unit) {
  var token = normalizeText(unit);
  if (!token) return '';
  if (token === 'cms' || token === 'centimeter' || token === 'centimeters' || token === 'centimetre' || token === 'centimetres' || token === 'سم') return 'cm';
  if (token === 'inch' || token === 'inches' || token === 'بوصة' || token === 'بوصات' || token === 'انش' || token === 'إنش') return 'in';
  if (token === 'lb' || token === 'lbs') return 'lbs';
  if (token === 'kilogram' || token === 'kilograms' || token === 'كجم' || token === 'كغ') return 'kg';
  if (token === 'رطل' || token === 'ارطال' || token === 'أرطال') return 'lbs';
  return token;
}

function inferGuideUnitFromText(text) {
  var normalizedText = String(text || '').toLowerCase();
  var unitCandidates = [
    'cm',
    'cms',
    'centimeter',
    'centimeters',
    'centimetre',
    'centimetres',
    'سم',
    'in',
    'inch',
    'inches',
    'بوصة',
    'بوصات',
    'انش',
    'إنش',
    'kg',
    'kgs',
    'kilogram',
    'kilograms',
    'كجم',
    'كغ',
    'lb',
    'lbs',
    'رطل',
    'ارطال',
    'أرطال',
  ];

  for (var index = 0; index < unitCandidates.length; index += 1) {
    var token = unitCandidates[index];
    var escaped = token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    var pattern = new RegExp('\\b' + escaped + '\\b', 'i');
    if (pattern.test(normalizedText)) return normalizeGuideUnit(token);
  }

  return '';
}

function splitGuideMeasurementParts(text) {
  return String(text || '')
    .split(/\s*\/\s*/)
    .map(function (part) {
      return String(part || '').trim();
    })
    .filter(Boolean);
}

function getGuideConvertibleUnits(unit) {
  var normalizedUnit = normalizeGuideUnit(unit);
  if (normalizedUnit === 'cm' || normalizedUnit === 'in') return ['cm', 'in'];
  if (normalizedUnit === 'kg' || normalizedUnit === 'lbs') return ['kg', 'lbs'];
  return [];
}

function mergeGuideUnitCandidates(targetUnits, candidateUnits) {
  (candidateUnits || []).forEach(function (unit) {
    if (unit && targetUnits.indexOf(unit) === -1) targetUnits.push(unit);
  });
}

function inferGuideUnitPairFromValues(columnValues) {
  var detectedUnits = [];

  (columnValues || []).forEach(function (value) {
    var parts = splitGuideMeasurementParts(value);

    if (parts.length) {
      parts.forEach(function (part) {
        mergeGuideUnitCandidates(detectedUnits, getGuideConvertibleUnits(inferGuideUnitFromText(part)));
      });
      return;
    }

    mergeGuideUnitCandidates(detectedUnits, getGuideConvertibleUnits(inferGuideUnitFromText(value)));
  });

  if (detectedUnits.indexOf('cm') !== -1 || detectedUnits.indexOf('in') !== -1) return ['cm', 'in'];
  if (detectedUnits.indexOf('kg') !== -1 || detectedUnits.indexOf('lbs') !== -1) return ['kg', 'lbs'];

  return [];
}

function inferGuideUnitPairFromLabel(labelText) {
  var normalizedLabel = normalizeText(labelText);
  if (!normalizedLabel) return [];
  if (normalizedLabel === 'size' || normalizedLabel === 'age' || normalizedLabel === '—') return [];

  if (normalizedLabel.indexOf('weight') !== -1) return ['kg', 'lbs'];

  var measurementTokens = [
    'height',
    'chest',
    'bust',
    'hip',
    'waist',
    'length',
    'sleeve',
    'shoulder',
    'pant',
    'short',
    'skirt',
    'garment',
  ];

  if (measurementTokens.some(function (token) {
    return normalizedLabel.indexOf(token) !== -1;
  })) {
    return ['cm', 'in'];
  }

  return [];
}

function inferGuideHeaderUnits(header, columnValues) {
  if (!header) return header;

  var normalizedUnits = (header.units || []).map(normalizeGuideUnit).filter(Boolean);
  if (normalizedUnits.length >= 2) return header;

  var inferredUnits = [];
  normalizedUnits.forEach(function (unit) {
    mergeGuideUnitCandidates(inferredUnits, getGuideConvertibleUnits(unit));
  });

  if (!inferredUnits.length) {
    mergeGuideUnitCandidates(inferredUnits, inferGuideUnitPairFromValues(columnValues));
  }

  if (!inferredUnits.length) {
    mergeGuideUnitCandidates(inferredUnits, inferGuideUnitPairFromLabel(header.label || header.raw || ''));
  }

  if (!inferredUnits.length) return header;

  return {
    raw: header.raw,
    label: header.label,
    units: inferredUnits,
  };
}

function enrichSizeGuideHeaders(headers, rows) {
  return (headers || []).map(function (header, index) {
    var columnValues = (rows || [])
      .map(function (row) {
        return row[index];
      })
      .filter(function (value) {
        return !isGuideEmptyValue(value);
      });

    return inferGuideHeaderUnits(header, columnValues);
  });
}

function cellText(cell) {
  return String(cell && cell.textContent ? cell.textContent : '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isGuideEmptyValue(value) {
  var text = String(value || '')
    .replace(/\s+/g, ' ')
    .trim();

  return !text || text === '—' || text === '-' || text === '--' || /^n\/a$/i.test(text);
}

function pruneGuideGroupColumns(headers, rows) {
  if (!headers || !headers.length || !rows || !rows.length) {
    return {
      headers: headers || [],
      rows: rows || [],
    };
  }

  var keepIndexes = headers
    .map(function (_header, index) {
      return index;
    })
    .filter(function (index) {
      if (index === 0) return true;

      return rows.some(function (row) {
        return !isGuideEmptyValue(row[index]);
      });
    });

  return {
    headers: keepIndexes.map(function (index) {
      return headers[index];
    }),
    rows: rows.map(function (row) {
      return keepIndexes.map(function (index) {
        return row[index];
      });
    }),
  };
}

function parseRoleFromHeader(header) {
  var cleaned = String(header && header.raw ? header.raw : header || '')
    .replace(/\s*\(.+?\)\s*$/, '')
    .trim();

  if (!cleaned) return null;

  var parsed = parseRoleFromSizeLabel(cleaned);
  if (parsed && parsed.sizeLabel) {
    return {
      key: parsed.key,
      label: parsed.label,
      measurement: cleanRoleHeaderMeasurement(parsed.sizeLabel),
    };
  }

  var normalizedHeader = normalizeText(cleaned);
  for (var index = 0; index < ROLE_DEFINITIONS.length; index += 1) {
    var roleDefinition = ROLE_DEFINITIONS[index];
    var aliasCandidates = getRoleAliasCandidates(roleDefinition);

    for (var aliasIndex = 0; aliasIndex < aliasCandidates.length; aliasIndex += 1) {
      var alias = aliasCandidates[aliasIndex];
      var normalizedAlias = normalizeText(alias);
      if (!normalizedAlias || normalizedAlias.length < 3) continue;
      if (/^[a-z0-9]+$/.test(normalizedAlias)) {
        var aliasPattern = new RegExp('(^|[^a-z0-9])' + escapeRegExp(normalizedAlias) + '([^a-z0-9]|$)', 'i');
        if (!aliasPattern.test(normalizedHeader)) continue;
      } else if (normalizedHeader.indexOf(normalizedAlias) === -1) {
        continue;
      }

      return {
        key: roleDefinition.key,
        label: getLocalizedRoleLabel(roleDefinition),
        measurement: cleanRoleHeaderMeasurement(stripRoleAliasFromHeader(cleaned, aliasCandidates)) || cleaned,
      };
    }
  }

  return null;
}

function stripRoleAliasFromHeader(header, aliases) {
  var measurement = String(header || '').trim();
  if (!measurement) return '';

  for (var index = 0; index < aliases.length; index += 1) {
    var alias = String(aliases[index] || '').trim();
    if (!alias) continue;

    var escapedAlias = escapeRegExp(alias).replace(/\s+/g, '\\s+');
    var aliasPattern = new RegExp('(^|\\s+|\\s*[-–/]\\s*)' + escapedAlias + '(?=\\s+|$|\\s*[-–/]\\s*)', 'i');
    if (!aliasPattern.test(measurement)) continue;

    return measurement.replace(aliasPattern, ' ').replace(/\s+/g, ' ').trim();
  }

  return measurement;
}

function cleanRoleHeaderMeasurement(value) {
  return String(value || '')
    .replace(/\s+(?:de|del|de la|do|da|dos|das|di|della|del|du|des|of|for)\s*$/i, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function buildSizeGuideGroups(parsed) {
  var rowGroups = {};

  parsed.rows.forEach(function (row) {
    var roleInfo = parseRoleFromSizeLabel(row[0]);
    if (!roleInfo) return;

    if (!rowGroups[roleInfo.key]) {
      rowGroups[roleInfo.key] = {
        key: roleInfo.key,
        label: roleInfo.label,
        helper: getRoleFitCopy(roleInfo.key),
        headers: [parsed.headers[0]].concat(parsed.headers.slice(1)),
        rows: [],
      };
    }

    rowGroups[roleInfo.key].rows.push([roleInfo.sizeLabel].concat(row.slice(1)));
  });

  var groupedRows = Object.keys(rowGroups)
    .map(function (key) {
      return rowGroups[key];
    })
    .filter(function (group) {
      return group.rows.length > 0;
    })
    .sort(function (first, second) {
      return getRoleOrder(first.key) - getRoleOrder(second.key);
    })
    .map(function (group) {
      var prunedGroup = pruneGuideGroupColumns(group.headers, group.rows);

      return {
        key: group.key,
        label: group.label,
        helper: group.helper,
        headers: prunedGroup.headers,
        rows: prunedGroup.rows,
      };
    });

  if (groupedRows.length > 1) return groupedRows;

  var heightIndex = parsed.headers.findIndex(function (header) {
    return isHeightLikeLabel(header && header.label ? header.label : '');
  });
  var groupedHeaders = {};

  parsed.headers.forEach(function (header, index) {
    if (index === 0 || index === heightIndex) return;
    var roleHeader = parseRoleFromHeader(header);
    if (!roleHeader) return;

    if (!groupedHeaders[roleHeader.key]) {
      groupedHeaders[roleHeader.key] = {
        label: roleHeader.label,
        helper: getRoleFitCopy(roleHeader.key),
        headers: [parsed.headers[0]],
        columnIndexes: [],
      };
      if (heightIndex > -1) groupedHeaders[roleHeader.key].headers.push(parsed.headers[heightIndex]);
    }

    groupedHeaders[roleHeader.key].headers.push({
      raw: parsed.headers[index].raw,
      label: roleHeader.measurement || parsed.headers[index].label,
      units: parsed.headers[index].units,
    });
    groupedHeaders[roleHeader.key].columnIndexes.push(index);
  });

  return Object.keys(groupedHeaders)
    .map(function (key) {
      var group = groupedHeaders[key];
      var rows = parsed.rows
        .map(function (row) {
          var hasRoleSpecificValue = group.columnIndexes.some(function (columnIndex) {
            return !isGuideEmptyValue(row[columnIndex]);
          });
          if (!hasRoleSpecificValue) return null;

          var rowValues = [row[0]];
          if (heightIndex > -1) rowValues.push(row[heightIndex]);
          group.columnIndexes.forEach(function (columnIndex) {
            rowValues.push(row[columnIndex]);
          });
          return rowValues;
        })
        .filter(function (rowValues) {
          return !!rowValues;
        });

      var prunedGroup = pruneGuideGroupColumns(group.headers, rows);

      return {
        key: key,
        label: group.label,
        headers: prunedGroup.headers,
        rows: prunedGroup.rows,
      };
    })
    .filter(function (group) {
      return group.rows.length > 0;
    })
    .sort(function (first, second) {
      return getRoleOrder(first.key) - getRoleOrder(second.key);
    });
}

function initPhotoReviewPanel(wrapper) {
  var panel = wrapper.querySelector('[data-photo-review-panel]');
  var media = wrapper.querySelector('[data-photo-review-media]');
  var title = wrapper.querySelector('.product-photo-strip__title');
  var reviewCount = parseInt(wrapper.getAttribute('data-product-review-count'), 10) || 0;
  var customerPhotosLabel = wrapper.getAttribute('data-customer-photos-label') || uiLabel('customerPhotos', 'Customer photos');
  var reviewRoot = document.getElementById('judgeme_product_reviews');
  if (!panel || !media || !reviewRoot) return;

  function populatePhotoPanel() {
    if (title && reviewCount <= 0) title.textContent = customerPhotosLabel;

    var links = Array.from(
      reviewRoot.querySelectorAll('.jdgm-rev__pics a, .jdgm-rev__pic-link, .jdgm-gallery__thumbnail-link, .jdgm-gallery__image-link')
    )
      .map(function (link) {
        var image = link.querySelector('img');
        if (!image || !image.getAttribute('src')) return null;
        return { href: link.getAttribute('href') || '#judgeme_product_reviews', src: image.getAttribute('src') };
      })
      .filter(Boolean)
      .slice(0, 4);

    if (!links.length) {
      panel.setAttribute('hidden', 'hidden');
      return;
    }

    media.innerHTML = links
      .map(function (item) {
        return (
          '<a href="' +
          escapeHtml(item.href) +
          '">' +
          '<img loading="lazy" src="' +
          escapeHtml(item.src) +
          '" alt="Customer review photo">' +
          '</a>'
        );
      })
      .join('');
    panel.removeAttribute('hidden');
  }

  populatePhotoPanel();

  var observer = new MutationObserver(populatePhotoPanel);
  observer.observe(reviewRoot, { childList: true, subtree: true });
}

function getRenderedPriceState(priceContainer) {
  if (!priceContainer) return null;

  var priceNode = priceContainer.querySelector('.price');
  var currentPrice = priceNode && priceNode.dataset ? priceNode.dataset.priceCurrentText : '';
  var compareAtPrice = priceNode && priceNode.dataset ? priceNode.dataset.priceCompareText : '';
  var isOnSale = priceNode && priceNode.dataset ? priceNode.dataset.priceOnSale === 'true' : false;

  if (!currentPrice) {
    var salePrice = priceContainer.querySelector('.price__sale .price-item--sale');
    var regularPrice = priceContainer.querySelector('.price__regular .price-item--regular');
    var fallbackPrice = priceContainer.querySelector('.price-item');
    var activePrice = salePrice || regularPrice || fallbackPrice;
    currentPrice = activePrice && activePrice.textContent ? activePrice.textContent.replace(/\s+/g, ' ').trim() : '';
  }

  return {
    currentPrice: currentPrice || '',
    compareAtPrice: compareAtPrice || '',
    isOnSale: isOnSale,
  };
}

function initDesktopStickyAtc(wrapper, sectionId) {
  var stickyBar = wrapper.parentElement.querySelector('[data-desktop-sticky-atc]');
  var stickyButton = stickyBar ? stickyBar.querySelector('[data-desktop-sticky-button]') : null;
  var stickyPrice = stickyBar ? stickyBar.querySelector('[data-desktop-sticky-price]') : null;
  var stickySize = stickyBar ? stickyBar.querySelector('[data-desktop-sticky-size]') : null;
  var variantSelects = document.getElementById('variant-selects-' + sectionId);
  var productForm = document.getElementById('product-form-' + sectionId);
  var mainButton = document.getElementById('ProductSubmitButton-' + sectionId);
  var matchingSetBuilder = wrapper.querySelector('[data-matching-set-builder]');
  var matchingSetButton = wrapper.querySelector('[data-matching-set-add-button]');
  var isMatchingSet = !!(matchingSetBuilder && matchingSetButton && !wrapper.closest('[data-matching-set-fallback="true"]'));
  var matchingSetStickyState =
    window.DLMMatchingSetStickyState && window.DLMMatchingSetStickyState[sectionId]
      ? window.DLMMatchingSetStickyState[sectionId]
      : null;
  var priceContainer = document.getElementById('price-' + sectionId);
  var desktopMedia = window.matchMedia('(min-width: 990px)');
  var buttonInView = true;
  var highlightedGroup = null;

  if (!stickyBar || !stickyButton) return;
  if (!mainButton && productForm) mainButton = productForm.querySelector('[name="add"]');
  if (isMatchingSet) mainButton = matchingSetButton;
  if (!mainButton) return;
  stickyBar.classList.toggle('sticky-desktop-atc--matching-set', isMatchingSet);

  function updatePrice() {
    if (!stickyPrice) return;
    if (isMatchingSet) {
      var hasSelectedPieces = !!(matchingSetStickyState && matchingSetStickyState.isReady);
      stickyPrice.textContent = hasSelectedPieces
        ? matchingSetStickyState.pieceCountLabel || wrapper.getAttribute('data-matching-set-add') || 'Matching pieces'
        : wrapper.getAttribute('data-matching-set-copy') || wrapper.getAttribute('data-matching-set-add') || 'Matching pieces';
      stickyPrice.removeAttribute('aria-label');
      stickyPrice.removeAttribute('title');
      return;
    }

    var priceState = getRenderedPriceState(priceContainer);
    if (!priceState || !priceState.currentPrice) return;

    stickyPrice.textContent = priceState.currentPrice;
    if (priceState.isOnSale && priceState.compareAtPrice && priceState.compareAtPrice !== priceState.currentPrice) {
      stickyPrice.setAttribute(
        'aria-label',
        priceState.currentPrice + ', compare at ' + priceState.compareAtPrice
      );
      stickyPrice.title = priceState.compareAtPrice;
      return;
    }

    stickyPrice.removeAttribute('aria-label');
    stickyPrice.removeAttribute('title');
  }

  function updateSize() {
    if (!stickySize || !variantSelects) return;
    if (isMatchingSet) {
      var hasSelectedPieces = !!(matchingSetStickyState && matchingSetStickyState.isReady);
      if (hasSelectedPieces && matchingSetStickyState.totalText) {
        stickySize.textContent = matchingSetStickyState.totalText;
        if (matchingSetStickyState.summaryText) {
          stickySize.title = matchingSetStickyState.summaryText;
          stickySize.setAttribute('aria-label', matchingSetStickyState.totalText + ': ' + matchingSetStickyState.summaryText);
        } else {
          stickySize.removeAttribute('title');
          stickySize.removeAttribute('aria-label');
        }
        stickySize.removeAttribute('hidden');
      } else {
        stickySize.textContent = '';
        stickySize.removeAttribute('title');
        stickySize.removeAttribute('aria-label');
        stickySize.setAttribute('hidden', 'hidden');
      }
      return;
    }

    var selectedSizes = [];

    Array.from(variantSelects.querySelectorAll('.product-form__input')).forEach(function (group) {
      if (!isVisibleGroup(group) || !isSizeGroup(group)) return;
      var value = getSelectedGroupValue(group);
      if (value) selectedSizes.push(value);
    });

    if (!selectedSizes.length) {
      stickySize.textContent = '';
      stickySize.setAttribute('hidden', 'hidden');
      return;
    }

    stickySize.textContent = selectedSizes.join(' / ');
    stickySize.removeAttribute('hidden');
  }

  function updateButtonState() {
    if (isMatchingSet) {
      var hasSelectedPieces = !!(matchingSetStickyState && matchingSetStickyState.isReady);
      stickyButton.textContent = hasSelectedPieces
        ? (matchingSetButton.textContent || wrapper.getAttribute('data-matching-set-add') || 'Add matching pieces').replace(/\s+/g, ' ').trim()
        : wrapper.getAttribute('data-choose-options-label') || 'Choose options';
      stickyButton.removeAttribute('disabled');
      stickyBar.classList.toggle('requires-options', !hasSelectedPieces);
      return;
    }

    var missingOption = getFirstMissingOption(variantSelects);
    var labelNode = mainButton.querySelector('span');
    var mainLabel = labelNode && labelNode.textContent ? labelNode.textContent.replace(/\s+/g, ' ').trim() : '';

    if (missingOption) {
      stickyButton.textContent = wrapper.getAttribute('data-select-size-label') || wrapper.getAttribute('data-choose-options-label');
      stickyButton.removeAttribute('disabled');
      return;
    }

    stickyButton.textContent = mainLabel || wrapper.getAttribute('data-add-to-cart-label') || 'Add to cart';
    if (mainButton.hasAttribute('disabled')) {
      stickyButton.setAttribute('disabled', 'disabled');
    } else {
      stickyButton.removeAttribute('disabled');
    }
  }

  function syncVisibility() {
    var shouldShow = desktopMedia.matches && !buttonInView;
    stickyBar.classList.toggle('is-visible', shouldShow);
    stickyBar.setAttribute('aria-hidden', shouldShow ? 'false' : 'true');
  }

  function alignMatchingSetForDrawer() {
    if (!matchingSetBuilder || typeof matchingSetBuilder.getBoundingClientRect !== 'function') return;

    var headerOffset = 120;
    var targetTop = matchingSetBuilder.getBoundingClientRect().top + window.scrollY - headerOffset;
    window.DLMCartDrawerOpenScrollY = Math.max(0, targetTop);
    window.scrollTo({
      top: window.DLMCartDrawerOpenScrollY,
      behavior: 'auto',
    });
  }

  stickyButton.addEventListener('click', function (event) {
    if (isMatchingSet) {
      if (!matchingSetStickyState || !matchingSetStickyState.isReady || matchingSetButton.hasAttribute('disabled')) {
        event.preventDefault();
        if (matchingSetBuilder && typeof matchingSetBuilder.scrollIntoView === 'function') {
          matchingSetBuilder.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        return;
      }
      alignMatchingSetForDrawer();
      matchingSetButton.click();
      return;
    }

    var missingOption = getFirstMissingOption(variantSelects);
    if (missingOption) {
      event.preventDefault();
      scrollToMissingOption(missingOption, function (group) {
        if (highlightedGroup && highlightedGroup !== group) {
          highlightedGroup.classList.remove('sticky-option-target--highlight');
        }

        highlightedGroup = group;
      });
      return;
    }

    if (mainButton.hasAttribute('disabled')) return;
    mainButton.click();
  });

  if (isMatchingSet) {
    document.addEventListener('dlm:matching-set-summary', function (event) {
      if (!event || !event.detail || event.detail.sectionId !== sectionId) return;
      matchingSetStickyState = event.detail;
      updatePrice();
      updateSize();
      updateButtonState();
      syncVisibility();
    });
  }

  var buttonObserver = new IntersectionObserver(
    function (entries) {
      entries.forEach(function (entry) {
        buttonInView = entry.isIntersecting;
        syncVisibility();
      });
    },
    { threshold: 0 }
  );
  buttonObserver.observe(mainButton);

  if (variantSelects) {
    variantSelects.addEventListener('change', function () {
      updateSize();
      updateButtonState();
    });
  }

  var buttonMutationObserver = new MutationObserver(updateButtonState);
  buttonMutationObserver.observe(mainButton, {
    attributes: true,
    attributeFilter: ['disabled'],
    childList: true,
    subtree: true,
    characterData: true,
  });

  if (priceContainer) {
    var priceObserver = new MutationObserver(updatePrice);
    priceObserver.observe(priceContainer, { childList: true, subtree: true, characterData: true });
  }

  function handleViewportChange() {
    if (!desktopMedia.matches) stickyBar.classList.remove('is-visible');
    syncVisibility();
  }

  if (typeof desktopMedia.addEventListener === 'function') {
    desktopMedia.addEventListener('change', handleViewportChange);
  } else if (typeof desktopMedia.addListener === 'function') {
    desktopMedia.addListener(handleViewportChange);
  }

  updatePrice();
  updateSize();
  updateButtonState();
  syncVisibility();
}

function isVisibleGroup(group) {
  if (!group) return false;
  var computedStyle = window.getComputedStyle(group);
  return computedStyle.display !== 'none' && computedStyle.visibility !== 'hidden';
}

function isSizeGroup(group) {
  if (!group) return false;
  var optionName = '';
  var control = group.querySelector('select[name], input[type="radio"][name]');
  if (control) optionName = getOptionNameFromControl(control);
  if (!optionName) {
    var label = group.querySelector('legend, label.form__label, .form__label');
    optionName = label ? label.textContent : '';
  }
  return isSizeLikeLabel(optionName);
}

function getSelectedGroupValue(group) {
  if (!group) return '';
  var select = group.querySelector('select');
  if (select) return String(select.value || '').trim();

  var checkedRadio = group.querySelector('input[type="radio"]:checked');
  if (checkedRadio) return String(checkedRadio.value || '').trim();

  return '';
}

function getFirstMissingOption(variantSelects) {
  if (!variantSelects) return null;

  var optionGroups = Array.from(variantSelects.querySelectorAll('.product-form__input')).filter(isVisibleGroup);

  for (var index = 0; index < optionGroups.length; index += 1) {
    var group = optionGroups[index];
    var select = group.querySelector('select');
    if (select && !select.value) {
      return {
        group: group,
        focusTarget: select,
        anchor: group.querySelector('label, legend, .form__label') || group,
      };
    }

    var radios = Array.from(group.querySelectorAll('input[type="radio"]'));
    if (radios.length && !group.querySelector('input[type="radio"]:checked')) {
      return {
        group: group,
        focusTarget: radios[0],
        anchor: group.querySelector('label, legend, .form__label') || group,
      };
    }
  }

  return null;
}

function scrollToMissingOption(missingOption, onHighlight) {
  if (!missingOption || !missingOption.group) return;

  missingOption.group.classList.add('sticky-option-target--highlight');
  if (typeof onHighlight === 'function') onHighlight(missingOption.group);

  window.setTimeout(function () {
    missingOption.group.classList.remove('sticky-option-target--highlight');
  }, 1400);

  var anchor = missingOption.anchor || missingOption.group;
  var offset = 120;
  var topPosition = window.scrollY + anchor.getBoundingClientRect().top - offset;
  window.scrollTo({ top: Math.max(topPosition, 0), behavior: 'smooth' });

  if (missingOption.focusTarget && typeof missingOption.focusTarget.focus === 'function') {
    try {
      missingOption.focusTarget.focus({ preventScroll: true });
    } catch (_error) {
      missingOption.focusTarget.focus();
    }
  }
}

