   Replaces the large inline size panel from rev 3. When the pill is
   SELECTED and not dismissed, the same compact black tooltip from the
   hover-preview pattern stays open (.is-pinned). Adds a tiny × and a
   cm/in toggle inside its header. Picking a different size on the
   same card re-opens the pinned tooltip for the new size.
   ───────────────────────────────────────────────────────────── */

/* Pinned variant — visible without :hover / :focus-within. */
.product__info-container--matching-set .product-matching-set__pill-tooltip.is-pinned {
  opacity: 1 !important;
  pointer-events: auto !important;
  transform: translate(-50%, 0) !important;
  /* a touch wider to accommodate the toggle + close button */
  min-width: 20rem;
}

/* A pinned tooltip needs to draw above neighbouring pills (and any
   neighbour's hover tooltip that might still be lurking). */
.product__info-container--matching-set .product-matching-set__pill-wrap:has(.is-pinned) {
  z-index: 35;
}

/* The hover-state base rule keeps the floating popover visible while
   hovering a wrap; for the pinned variant we don't want hovering a
   neighbor to dim ours, so explicit re-statement above with !important. */

/* Header row inside the tooltip: title on the left, controls on the
   right when pinned. */
.product__info-container--matching-set .product-matching-set__pill-tooltip-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  margin-bottom: 0.4rem;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-controls {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  flex: 0 0 auto;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-toggle {
  display: inline-flex;
  padding: 0.15rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-unit {
  min-width: 2.4rem;
  padding: 0.18rem 0.55rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-unit:hover {
  color: #ffffff;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-unit.is-active {
  background: #ffffff;
  color: #1a1a1a;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-close {
  width: 1.9rem;
  height: 1.9rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease;
}

.product__info-container--matching-set .product-matching-set__pill-tooltip-close:hover,
.product__info-container--matching-set .product-matching-set__pill-tooltip-close:focus-visible {
  background: rgba(255, 255, 255, 0.22);
  outline: none;
}

/* On narrow viewports keep the pinned tooltip readable but not huge —
   it positions over the pill row, so the size-blurb confirmation
   beneath the pills tells the shopper what they picked even when the
   tooltip overlaps something. */
@media screen and (max-width: 480px) {
  .product__info-container--matching-set .product-matching-set__pill-tooltip.is-pinned {
    min-width: 18rem;
  }
}

/* 7. Quantity stepper + per-card price chip. */
.product__info-container--matching-set .product-matching-set__qty {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  margin-top: 0.4rem;
}
.product__info-container--matching-set .product-matching-set__qty-button {
  width: 3.4rem;
  height: 3.4rem;
  padding: 0;
  border: 0.12rem solid rgba(17, 24, 39, 0.16);
  border-radius: 999px;
  background: #ffffff;
  color: #101418;
  font-size: 1.55rem;
  font-weight: 700;
  line-height: 1;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
}
.product__info-container--matching-set .product-matching-set__qty-button:hover {
  border-color: #1D8656;
  color: #1D8656;
}
.product__info-container--matching-set .product-matching-set__qty-value {
  min-width: 2.2rem;
  font-size: 1.25rem;
  font-weight: 700;
  text-align: center;
  color: #101418;
}
/* "Pick a size for {role}" prompt — shown beneath the pills when a
   card has no variant selected. Soft amber so it reads as guidance,
   not error. */
.product__info-container--matching-set .product-matching-set__pick-hint {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.5rem 0 0.4rem;
  padding: 0.55rem 0.85rem;
  border-radius: 0.9rem;
  background: #fff5e0;
  border: 0.1rem solid rgba(180, 120, 30, 0.18);
  color: #8a5a18;
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.35;
}
.product__info-container--matching-set .product-matching-set__pick-hint svg {
  flex: 0 0 auto;
}

/* Inline contextual prompt — small, subtle, sits directly under the
   row it refers to (size pill row OR axis row). Less heavy than the
   full-width amber banner and reads as natural microcopy adjacent to
   the control it guides. Disappears as soon as the row has a value. */
.product__info-container--matching-set .product-matching-set__inline-hint {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin: 0.35rem 0 0;
  padding: 0;
  color: #b07820;
  font-size: 1rem;
  font-weight: 600;
  font-style: italic;
  line-height: 1.3;
  letter-spacing: 0.01em;
}
.product__info-container--matching-set .product-matching-set__inline-hint::before {
  content: '↑';
  display: inline-block;
  margin-right: 0.1rem;
  font-style: normal;
  font-weight: 800;
  color: #d39c4a;
}

/* Friendly confirmation line — shown beneath the pills once a size
   is picked. Replaces the dense WEIGHT/HEIGHT/CHEST grid that used
   to dominate the viewport. Full measurements still reachable via
   the per-card "Find {role}'s fit →" link below. */
.product__info-container--matching-set .product-matching-set__size-blurb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.5rem 0 0.4rem;
  padding: 0.55rem 0.85rem;
  border-radius: 0.9rem;
  background: rgba(29, 134, 86, 0.08);
  border: 0.1rem solid rgba(29, 134, 86, 0.18);
  color: #146642;
  font-size: 1.1rem;
  font-weight: 600;
  line-height: 1.35;
}
.product__info-container--matching-set .product-matching-set__size-blurb svg {
  flex: 0 0 auto;
}
.product__info-container--matching-set .product-matching-set__size-blurb-text strong {
  font-weight: 800;
  color: #101418;
}

/* 8. Progressive "+ Add Dad / + Add Baby" chip row. */
.product__info-container--matching-set .product-matching-set__add-roles {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 0.9rem;
}
.product__info-container--matching-set .product-matching-set__add-role {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 3.8rem;
  padding: 0 1.3rem;
  border: 0.12rem dashed rgba(29, 134, 86, 0.55);
  border-radius: 999px;
  background: transparent;
  color: #1D8656;
  font-size: 1.15rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease, color 0.12s ease;
}
.product__info-container--matching-set .product-matching-set__add-role:hover {
  background: rgba(29, 134, 86, 0.08);
  border-color: #1D8656;
  color: #146642;
}

/* Caption when there are no more roles to add — clarifies the scope
   of the set so shoppers don't mistake the absence of "+ Add" buttons
   for a broken UI. */
.product__info-container--matching-set .product-matching-set__roles-note {
  margin: 0.8rem 0 0;
  font-size: 1.05rem;
  color: rgba(17, 24, 39, 0.55);
  font-style: italic;
}

/* 9. Live summary above the CTA. */
.product__info-container--matching-set .product-matching-set__summary {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin: 1.1rem 0 0.9rem;
  padding: 0.9rem 1.1rem;
  border-radius: 1.2rem;
  background: rgba(29, 134, 86, 0.06);
  border: 0.1rem solid rgba(29, 134, 86, 0.16);
}
.product__info-container--matching-set .product-matching-set__summary[hidden] {
  display: none;
}
.product__info-container--matching-set .product-matching-set__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.product__info-container--matching-set .product-matching-set__chip {
  font-size: 1.1rem;
  font-weight: 700;
  color: #146642;
  letter-spacing: 0.01em;
}
.product__info-container--matching-set .product-matching-set__chip--count {
  background: transparent;
  padding: 0;
  border: 0;
}
.product__info-container--matching-set .product-matching-set__chip--ready {
  color: #1D8656;
}
.product__info-container--matching-set .product-matching-set__chip--selection {
  color: #101418;
}
.product__info-container--matching-set .product-matching-set__total {
  font-size: 1.45rem;
  font-weight: 600;
  color: rgba(17, 24, 39, 0.78);
}
.product__info-container--matching-set .product-matching-set__total strong {
  margin-left: 0.4rem;
  font-size: 1.7rem;
  font-weight: 800;
  color: #101418;
}
.product__info-container--matching-set .product-matching-set__savings {
  font-size: 1.1rem;
  font-weight: 700;
  color: #1D8656;
}
.product__info-container--matching-set .product-matching-set__empty {
  margin: 0;
  font-size: 1.15rem;
  color: rgba(17, 24, 39, 0.6);
}

/* 10. Primary CTA — restored to filled-green as THE one button. */
.product__info-container--matching-set .product-matching-set__footer {
  margin: 0;
}
.product__info-container--matching-set .product-matching-set__button {
  width: 100%;
  min-width: 0;
  min-height: 5.4rem;
  padding: 0 2rem;
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #1D8656 0%, #146642 100%);
  color: #ffffff;
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  box-shadow: 0 0.4rem 1.2rem rgba(29, 134, 86, 0.28);
  transition: transform 0.05s ease, box-shadow 0.15s ease, background 0.15s ease;
}
.product__info-container--matching-set .product-matching-set__button:hover:not([disabled]) {
  background: linear-gradient(135deg, #146642 0%, #0f5235 100%);
  color: #ffffff;
  box-shadow: 0 0.5rem 1.6rem rgba(29, 134, 86, 0.36);
}
.product__info-container--matching-set .product-matching-set__button:focus-visible:not([disabled]) {
  color: #ffffff;
}
.product__info-container--matching-set .product-matching-set__button:active:not([disabled]) {
  color: #ffffff;
  transform: translateY(1px);
}
.product__info-container--matching-set .product-matching-set__button::before,
.product__info-container--matching-set .product-matching-set__button::after {
  content: none;
}
.product__info-container--matching-set .product-matching-set__button[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
}

/* 11. Compact trust row directly under the CTA. */
.product__info-container--matching-set .product-matching-set__trust {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem 1.3rem;
  margin: 0.9rem 0 0;
  padding: 0;
  list-style: none;
  font-size: 1.1rem;
  color: rgba(17, 24, 39, 0.68);
}
.product__info-container--matching-set .product-matching-set__trust li {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}
.product__info-container--matching-set .product-matching-set__trust span {
  color: #1D8656;
  font-weight: 800;
}

/* 12. Status (success / error after add-to-cart). */
.product__info-container--matching-set .product-matching-set__status {
  margin: 0.8rem 0 0;
  padding: 0.7rem 0.9rem;
  border-radius: 0.8rem;
  background: rgba(29, 134, 86, 0.08);
  color: #146642;
  font-size: 1.1rem;
}

/* 13. Mobile spacing — extra tight on phones to keep CTA in viewport. */
@media screen and (max-width: 749px) {
  .product__info-container--matching-set .product-matching-set {
    margin: 0.8rem 0 1rem;
    padding: 1.1rem 1.1rem 1rem;
  }
  .product__info-container--matching-set .product-matching-set__title {
    font-size: 1.55rem;
  }
  .product__info-container--matching-set .product-matching-set__card {
    padding: 1rem;
  }
  .product__info-container--matching-set .product-matching-set__role-buttons {
    grid-template-columns: 1fr;
  }
}

/* ─────────────────────────────────────────────────────────────────
   Price block + "Save X%" pill (CRO redesign May 2026)
   The pill is rendered server-side in main-product.liquid when a
   compare-at price is set. Styled here so the savings reads at a
   glance and the sale price reads as the dominant price.
   ───────────────────────────────────────────────────────────── */
.pdp-save-pill {
  display: inline-block;
  margin-left: 0.6rem;
  padding: 0.25rem 0.7rem;
  border-radius: 999px;
  background: #fce8e2;
  color: #c2410c;
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  vertical-align: middle;
  text-transform: uppercase;
}

.product__info-container--matching-set .price .price-item--sale {
  font-weight: 800;
  color: #1a1a1a;
}
.product__info-container--matching-set .price s.price-item--regular,
.product__info-container--matching-set .price .price-item--regular {
  font-size: 0.85em;
  color: rgba(17, 24, 39, 0.55);
}
.product__info-container--matching-set .price--range .price-item--regular {
  font-size: 1em;
  font-weight: 800;
  color: #111418;
}
.product__info-container--matching-set .pdp-save-pill {
  background: #e8f6ee;
  color: #146642;
}

.product__info-container--matching-set .price__badge-sale {
  display: none !important;
}

