}

.article-template__recommended-product-title a {
  color: inherit;
  text-decoration: none;
}

.article-template__recommended-price .price__container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem 1.2rem;
  align-items: baseline;
}

.article-template__recommended-price .price-item {
  font-size: 1.6rem;
}

.article-template__recommended-product-link {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  color: inherit;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: 0.08rem;
  text-decoration: none;
  text-transform: uppercase;
}

.article-template__recommended-fallback-link {
  min-width: 0;
}

@media screen and (min-width: 750px) {
  .article-template__recommended-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.article-template__related {
  margin-top: 5rem;
}

.article-template__related-header {
  display: grid;
  gap: 1rem;
  margin-bottom: 2rem;
}

.article-template__related-grid {
  display: grid;
  gap: 2rem;
}

.article-template__comment-wrapper {
  margin-top: 5rem;
  padding: 2.7rem 0;
}

@media screen and (min-width: 750px) {
  .article-template__shop-card {
    padding: 3rem;
  }

  .article-template__shop-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .article-template__related {
    margin-top: 6rem;
  }

  .article-template__related-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .article-template__comment-wrapper {
    margin-top: 6rem;
    padding: 3.6rem 0;
  }
}

.article-template__comment-wrapper h2 {
  margin-top: 0;
}

.article-template__comments {
  margin-bottom: 5rem;
}

@media screen and (min-width: 750px) {
  .article-template__comments {
    margin-bottom: 7rem;
  }
}

.article-template__comments-fields {
  margin-bottom: 4rem;
}

.article-template__comments-comment {
  color: rgba(var(--color-foreground), 0.75);
  background-color: rgb(var(--color-background));
  margin-bottom: 1.5rem;
  padding: 2rem 2rem 1.5rem;
}

@media screen and (min-width: 750px) {
  .article-template__comments-comment {
    padding: 2rem 2.5rem;
  }
}

.article-template__comments-comment p {
  margin: 0 0 1rem;
}

.article-template__comment-fields > * {
  margin-bottom: 3rem;
}

@media screen and (min-width: 750px) {
  .article-template__comment-fields {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-column-gap: 4rem;
  }
}

.article-template__comment-warning {
  margin: 2rem 0 2.5rem;
}

@media screen and (min-width: 990px) {
  .article-template__comments .pagination-wrapper {
    margin: 5rem 0 8rem;
  }
}

.article-template__back:last-child {
  margin-bottom: 3.2rem;
}

/* ── Author Bio ── */
.article-template__author {
  margin-top: 4rem;
}

.article-template__author-card {
  display: flex;
  gap: 2rem;
  padding: 2.4rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2rem;
  background: rgba(var(--color-foreground), 0.02);
}

.article-template__author-avatar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 5.6rem;
  height: 5.6rem;
  border-radius: 50%;
  background: rgba(var(--color-foreground), 0.08);
  font-size: 2rem;
  font-weight: 700;
  color: rgba(var(--color-foreground), 0.7);
}

.article-template__author-info {
  display: grid;
  gap: 0.4rem;
}

.article-template__author-label {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

.article-template__author-name {
  margin: 0;
  font-size: 1.8rem;
  font-weight: 600;
}

.article-template__author-bio {
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.65;
  color: rgba(var(--color-foreground), 0.7);
}

/* ── Table of Contents ── */
.article-toc {
  margin-bottom: 3.2rem;
  padding: 2.2rem 2.4rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2rem;
  background: rgba(var(--color-foreground), 0.02);
}

.article-toc__label {
  margin: 0 0 1.2rem;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

.article-toc__list {
  margin: 0;
  padding-left: 2rem;
  list-style: decimal;
}

.article-toc__list li {
  margin-bottom: 0.6rem;
  font-size: 1.5rem;
  line-height: 1.5;
}

.article-toc__list a {
  color: rgba(var(--color-foreground), 0.85);
  text-decoration: none;
  border-bottom: 0.1rem solid rgba(var(--color-foreground), 0.12);
  transition: color 0.2s ease, border-color 0.2s ease;
}

.article-toc__list a:hover {
  color: rgb(var(--color-foreground));
  border-color: rgba(var(--color-foreground), 0.4);
}

/* ── Mid-Article CTA ── */
.article-cta-inline {
  margin: 3.2rem auto;
  padding: 2.4rem;
  border-radius: 2rem;
  background: linear-gradient(135deg, rgba(var(--color-foreground), 0.03) 0%, rgba(var(--color-foreground), 0.06) 100%);
  text-align: center;
}

.article-cta-inline__text {
  margin: 0 0 1.2rem;
  font-size: 1.8rem;
  font-weight: 600;
  color: rgb(var(--color-foreground));
}

.article-template__content .article-cta-inline__button.button {
  display: inline-block;
  color: rgb(var(--color-button-text));
}

/* ── Improved Heading Hierarchy ── */
.article-template__content h2 {
  font-size: clamp(2.4rem, 4vw, 3.2rem);
  font-weight: 700;
  margin-top: 4.8rem;
  margin-bottom: 1.8rem;
  padding-bottom: 1rem;
  border-bottom: 0.1rem solid rgba(var(--color-foreground), 0.08);
}

.article-template__content h3 {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  font-weight: 600;
  margin-top: 3.2rem;
  margin-bottom: 1.2rem;
  color: rgba(var(--color-foreground), 0.9);
}

.article-template__content h4 {
  font-size: clamp(1.6rem, 2.5vw, 2rem);
  font-weight: 600;
  margin-top: 2.4rem;
  margin-bottom: 1rem;
  color: rgba(var(--color-foreground), 0.82);
}

/* ── Shop Module Arrow ── */
.article-template__shop-arrow {
  font-size: 1.8rem;
  transition: transform 0.2s ease;
}

.article-template__shop-link:hover .article-template__shop-arrow {
  transform: translateX(0.4rem);
}

/* ── Read Time Tag ── */
.article-template__read-time {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 1.1rem;
  letter-spacing: 0.18rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

/* ── Author Credential Badge ── */
.article-template__author-credential {
  display: inline-block;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.08rem;
  color: rgba(var(--color-foreground), 0.55);
  padding-left: 0.6rem;
}

/* ── Social Proof / Testimonial ── */
.article-template__social-proof {
  margin-top: 3.2rem;
}

.article-template__testimonial-card {
  padding: 2.4rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2rem;
  background: rgba(var(--color-foreground), 0.02);
  text-align: center;
}

.article-template__testimonial-label {
  margin: 0 0 1.2rem;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

.article-template__testimonial-title {
  margin: 0;
  font-size: clamp(2.2rem, 3vw, 3rem);
  line-height: 1.12;
}

.article-template__testimonial-text {
  max-width: 58rem;
  margin: 1rem auto 0;
  font-size: 1.6rem;
  line-height: 1.7;
  color: rgba(var(--color-foreground), 0.72);
}

.article-template__testimonial-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-top: 1.8rem;
}

{%- assign dlm_cart_language = request.locale.iso_code | split: '-' | first -%}
{{ 'component-cart.css' | asset_url | stylesheet_tag }}
{{ 'component-totals.css' | asset_url | stylesheet_tag }}
{{ 'component-price.css' | asset_url | stylesheet_tag }}
{{ 'component-discounts.css' | asset_url | stylesheet_tag }}

{%- style -%}
  .section-{{ section.id }}-padding {
    padding-top: {{ section.settings.padding_top | times: 0.75 | round: 0 }}px;
    padding-bottom: {{ section.settings.padding_bottom | times: 0.75 | round: 0 }}px;
  }

  @media screen and (min-width: 750px) {
    .section-{{ section.id }}-padding {
      padding-top: {{ section.settings.padding_top }}px;
      padding-bottom: {{ section.settings.padding_bottom }}px;
    }
  }
{%- endstyle -%}

<div
  class="gradient color-{{ section.settings.color_scheme }}{% if cart == empty %} is-empty{% endif %}"
  id="main-cart-footer"
  data-id="{{ section.id }}"
>
  <div class="page-width">
    <div class="cart__footer isolate section-{{ section.id }}-padding">
      {%- if settings.show_cart_note -%}
        <cart-note class="cart__note field">
          <label for="Cart-note">{{ 'sections.cart.note' | t }}</label>
          <textarea
            class="text-area field__input"
            name="note"
            form="cart"
            id="Cart-note"
            placeholder="{{ 'sections.cart.note' | t }}"
          >{{ cart.note }}</textarea>
        </cart-note>
      {%- endif -%}

      <div class="cart__blocks">
        {%- comment -%} Discount code field — matches cart drawer {%- endcomment -%}
        {%- if cart != empty -%}
          <div class="cart-page__discount">
            <div class="cart-page__discount-toggle">
              <button type="button" class="cart-page__discount-btn" aria-expanded="false" onclick="this.setAttribute('aria-expanded', this.getAttribute('aria-expanded') === 'false' ? 'true' : 'false'); this.closest('.cart-page__discount').querySelector('.cart-page__discount-form').classList.toggle('is-open');">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
                {{ 'sections.cart.discount_code_toggle' | t }}
              </button>
            </div>
            <div class="cart-page__discount-form">
              <div class="cart-page__discount-input-wrap">
                <input type="text" class="cart-page__discount-input field__input" placeholder="Discount code" id="CartPage-Discount" autocomplete="off">
                <button type="button" class="cart-page__discount-apply button button--secondary" onclick="
                  var code = document.getElementById('CartPage-Discount').value;
                  if(!code) return;
                  var btn = this;
                  btn.disabled = true;
                  btn.textContent = '...';
                  fetch('/discount/' + encodeURIComponent(code))
                    .then(function() { return fetch('/cart.js'); })
                    .then(function(r) { return r.json(); })
                    .then(function(cart) {
                      btn.disabled = false;
                      btn.textContent = 'Apply';
                      if(cart.total_discount > 0 || cart.cart_level_discount_applications.length > 0) {
                        var wrap = btn.closest('.cart-page__discount');
                        wrap.innerHTML = '<div class=\'cart-page__discount-success\'><svg width=\'14\' height=\'14\' viewBox=\'0 0 24 24\' fill=\'none\' stroke=\'#2e7d32\' stroke-width=\'2\' aria-hidden=\'true\'><polyline points=\'20 6 9 17 4 12\'/></svg> Code <strong>' + code + '</strong> applied!</div>';
                        location.reload();
                      } else {
                        var input = document.getElementById('CartPage-Discount');
                        input.style.borderColor = '#c62828';
                        var existing = btn.parentNode.parentNode.querySelector('.cart-page__discount-error');
                        if(!existing) {
                          var err = document.createElement('p');
                          err.className = 'cart-page__discount-error';
                          err.textContent = 'Invalid or expired code';
                          btn.parentNode.after(err);
                        }
                      }
                    })
                    .catch(function() { btn.disabled = false; btn.textContent = 'Apply'; });
                ">Apply</button>
              </div>
            </div>
          </div>
        {%- endif -%}

        {% for block in section.blocks %}
          {%- case block.type -%}
            {%- when '@app' -%}
              {% render block %}
            {%- when 'subtotal' -%}
              <div class="js-contents" {{ block.shopify_attributes }}>
                <div>
                  {%- if cart.cart_level_discount_applications.size > 0 -%}
                    <ul class="discounts list-unstyled" role="list" aria-label="{{ 'customer.order.discount' | t }}">
                      {%- for discount in cart.cart_level_discount_applications -%}
                        <li class="discounts__discount discounts__discount--position">
                          {%- render 'icon-discount' -%}
                          {{ discount.title }}
                          (-{{ discount.total_allocated_amount | money }})
                        </li>
                      {%- endfor -%}
                    </ul>
                  {%- endif -%}
                </div>

                {%- comment -%} Savings summary — matches cart drawer {%- endcomment -%}
                {%- assign total_savings = 0 -%}
                {%- for item in cart.items -%}
                  {%- if item.original_line_price > item.final_line_price -%}
                    {%- assign item_savings = item.original_line_price | minus: item.final_line_price -%}
                    {%- assign total_savings = total_savings | plus: item_savings -%}
                  {%- endif -%}
                {%- endfor -%}
                {%- if total_savings > 0 -%}
                  <div class="cart-savings">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
                    {%- assign savings_amount = total_savings | money -%}
                    {{ 'sections.cart.savings_html' | t: amount: savings_amount }}
                  </div>
                {%- endif -%}

                <div class="cart-page__shipping-line">
                  <span>{{ 'sections.cart.shipping_label' | t }}</span>
                  <span class="cart-page__shipping-free">{{ 'sections.cart.shipping_free' | t }}</span>
                </div>
                <div class="cart-page__country-checker">
                  {% render 'shipping-country-checker-trigger', context: 'cart' %}
                </div>
                <div class="totals">
                  <h2 class="totals__total">{{ 'sections.cart.estimated_total' | t }}</h2>
                  <p class="totals__total-value">{{ cart.total_price | money_with_currency }}</p>
                </div>

                <div class="cart-page__checkout-note caption-large">
                  <span>
                    {%- if cart.taxes_included -%}
                      {%- if dlm_cart_language == 'fr' -%}Taxes incluses.{%- else -%}Taxes included.{%- endif -%}
                    {%- else -%}
                      {%- if dlm_cart_language == 'fr' -%}Taxes calculées au paiement.{%- else -%}Taxes calculated at checkout.{%- endif -%}
                    {%- endif -%}
                  </span>
                  {%- if shop.shipping_policy.body != blank -%}
                    <details class="cart-page__policy-details">
                      <summary>{% if dlm_cart_language == 'fr' %}Détails de la livraison{% else %}Shipping details{% endif %}</summary>
                      <div class="rte">
                        {{ shop.shipping_policy.body }}
                      </div>
                    </details>
                  {%- endif -%}
                </div>
              </div>
            {%- else -%}
              {%- comment -%} Delivery timing remains hidden until address-specific checkout rates are confirmed. {%- endcomment -%}
              <div class="cart-page__delivery-estimate" hidden>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
                {{ 'sections.cart.order_today_delivery' | t }} <strong><span class="js-delivery-date"></span></strong>
              </div>

              {%- comment -%} Storewide aggregate rating removed pending owner-provided proof. {%- endcomment -%}

              <div class="cart__ctas" {{ block.shopify_attributes }}>
                <button
                  type="submit"
                  id="checkout"
                  class="cart__checkout-button button"
                  name="checkout"
                  {% if cart == empty %}
                    disabled
                  {% endif %}
                  form="cart"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="margin-right:6px" aria-hidden="true"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
                  {{ 'sections.cart.checkout' | t }}
                </button>
              </div>

              {%- if additional_checkout_buttons -%}
                <div class="cart__dynamic-checkout-buttons additional-checkout-buttons">
                  {{ content_for_additional_checkout_buttons }}
                </div>
              {%- endif -%}

              <!-- Trust badges for cart page (matches cart drawer) -->
              <div class="cart-page__trust-badges">
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
                  <span>{{ 'sections.cart.trust.secure_checkout' | t }}</span>
                </div>
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
                  <span>{{ 'sections.cart.trust.ssl_encrypted' | t }}</span>
                </div>
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                  <span>{{ 'sections.cart.trust.free_shipping' | t }}</span>
                </div>
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"/></svg>
                  <span>{{ 'sections.cart.trust.returns' | t }}</span>
                </div>
              </div>

              <!-- Accepted payment methods (matches cart drawer) -->
              <div class="cart-page__payment-icons">
                <span class="payment-icons__label">{{ 'sections.cart.we_accept' | t }}</span>
                <div class="payment-icons__list">
                  {%- for type in shop.enabled_payment_types -%}
                    {{ type | payment_type_svg_tag: class: 'payment-icon' }}
                  {%- endfor -%}
                </div>
              </div>

              {%- comment -%} Complete the Look — moved below all checkout elements {%- endcomment -%}
              {%- if cart != empty -%}
                <div class="cart-page__cross-sell">
                  <h2 class="cart-page__cross-sell-heading">{{ 'sections.cart.complete_the_look' | t }}</h2>
                  <div class="cart-page__cross-sell-grid">
                    {%- assign first_item = cart.items | first -%}
                    {%- assign cross_sell_count = 0 -%}
                    {%- for collection in first_item.product.collections -%}
                      {%- if cross_sell_count >= 4 -%}{%- break -%}{%- endif -%}
                      {%- for product in collection.products limit: 8 -%}
                        {%- if cross_sell_count >= 4 -%}{%- break -%}{%- endif -%}
                        {%- assign in_cart = false -%}
                        {%- for item in cart.items -%}
                          {%- if item.product.id == product.id -%}
                            {%- assign in_cart = true -%}
                            {%- break -%}
                          {%- endif -%}
                        {%- endfor -%}
                        {%- unless in_cart -%}
                          <div class="cart-page__cross-sell-item">
                            <a href="{{ product.url }}" class="cart-page__cross-sell-img-link">
                              {%- if product.featured_image -%}
                                <div class="cart-page__cross-sell-img-wrap">
                                  <img
                                    src="{{ product.featured_image | image_url: width: 400 }}"
                                    alt="{{ product.featured_image.alt | escape }}"
                                    width="150"
                                    height="{{ 150 | divided_by: product.featured_image.aspect_ratio | ceil }}"
                                    loading="lazy"
                                    class="cart-page__cross-sell-img"
                                  >
                                </div>
                              {%- endif -%}
                            </a>
                            <div class="cart-page__cross-sell-info">
                              <a href="{{ product.url }}" class="cart-page__cross-sell-name">{{ product.title | escape | split: ' | ' | first }}</a>
                              <span class="cart-page__cross-sell-price">{{ product.price | money }}</span>
                            </div>
                          </div>
                          {%- assign cross_sell_count = cross_sell_count | plus: 1 -%}
                        {%- endunless -%}
                      {%- endfor -%}
                    {%- endfor -%}
                  </div>
                </div>
              {%- endif -%}

          {%- endcase -%}
        {% endfor %}

        <div id="cart-errors"></div>
      </div>
    </div>
  </div>
</div>

{% schema %}
{
  "name": "t:sections.main-cart-footer.name",
  "class": "cart__footer-wrapper",
  "settings": [
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "label": "t:sections.all.colors.label",
      "default": "scheme-1"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_top",
      "default": 40
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_bottom",
      "default": 40
    }
  ],
  "blocks": [
    {
      "type": "subtotal",
      "name": "t:sections.main-cart-footer.blocks.subtotal.name",
      "limit": 1
    },
    {
      "type": "buttons",
      "name": "t:sections.main-cart-footer.blocks.buttons.name",
